alter table public.profiles add column if not exists first_name text, add column if not exists second_name text, add column if not exists full_name text, add column if not exists phone text;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ declare workspace_id uuid; begin insert into public.profiles(id,first_name,second_name,full_name,phone) values(new.id,new.raw_user_meta_data->>'first_name',new.raw_user_meta_data->>'second_name',new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'phone') on conflict (id) do update set first_name=excluded.first_name,second_name=excluded.second_name,full_name=excluded.full_name,phone=excluded.phone; insert into public.workspaces(owner_id) values(new.id) returning id into workspace_id; insert into public.workspace_members(workspace_id,user_id,role) values(workspace_id,new.id,'owner'); return new; end; $$;
revoke execute on function public.handle_new_user() from anon, authenticated;
